command:
node --input-type=module -e "import fs from 'node:fs';import crypto from 'node:crypto';import path from 'node:path';
const p='.flow/artifacts/fn-109-gomad-deepen-modules-and-tool-interfaces/task-50/generator-stderr-20261009';
const b=n=>fs.readFileSync(path.join(p,n)),h=v=>crypto.createHash('sha256').update(v).digest('hex');
const e=JSON.parse(b('evidence.json')),seal=JSON.parse(b('packet-seal-receipt.json'));let streams=0,bindings=0,receipts=0;
for(const n of fs.readdirSync(p).filter(n=>n.endsWith('-receipt.json'))){const r=JSON.parse(b(n));receipts++;
if(!Number.isInteger(r.child_exit_code)||r.signal||r.error||!r.source_unchanged||!r.tools_unchanged||!r.controls_unchanged)throw Error('receipt stability '+n);
for(const k of ['source','tools','controls']){if(h(b(r[k].manifest))!==r[k].sha256)throw Error('manifest '+n);bindings++;}
for(const k of ['stdout','stderr']){if(h(b(r[k].path))!==r[k].sha256)throw Error('stream '+n);streams++;}
const records=b(r.stdout.path).toString().split('\n').filter(s=>s.startsWith('{')).flatMap(s=>{try{return[JSON.parse(s)];}catch{return[];}});
for(const a of ['pass','fail','skip'])if(records.filter(x=>x.Action===a&&x.Test).length!==r.counts[a])throw Error('counts '+n);
for(const ent of JSON.parse(b(r.controls.manifest)).filter(x=>/\.(mjs|md|sh|json|go)$/.test(x.path))){if(h(b('control-'+ent.sha256+path.extname(ent.path)))!==ent.sha256)throw Error('control archive '+n);}}
for(const ent of e.receipts)if(h(b(ent.receipt))!==ent.sha256)throw Error('worker receipt hash');
for(const k of ['source','tools','controls'])for(const ent of JSON.parse(b(seal[k].manifest)))if(h(fs.readFileSync(ent.path))!==ent.sha256)throw Error('current sealed input '+ent.path);
for(const [r,w] of [['root-generator-scoped-lint','scoped-analyzer-final'],['root-generator-integrated-lint','integrated-original-final']])if(!b(r+'.stdout').equals(b(w+'.stdout')))throw Error('root lint differs');
const errors=n=>b(n+'.stdout').toString().trim().split('\n').map(s=>JSON.parse(s)).filter(x=>x.OutputType?.startsWith('error')).map(x=>({test:x.Test,output:x.Output}));
if(JSON.stringify(errors('ordinary-package-final-offline-proxy'))!==JSON.stringify(errors('ordinary-package-baseline-offline-proxy')))throw Error('worker full diagnostic bytes differ');
console.log(JSON.stringify({receipts,streams,bindings,sealed_worker_receipts:e.receipts.length+1,source_inputs:JSON.parse(b(seal.source.manifest)).length,tools:JSON.parse(b(seal.tools.manifest)).length,controls:JSON.parse(b(seal.controls.manifest)).length,root_lint_byte_equal:true,root_full_package_errors:errors('root-generator-ordinary-package'),historical_proof_controls:e.final_proof_controls.sha256,current_sealing_controls:seal.controls.sha256}));"

